'use strict';
const KEY='yiyu-life-v1';
const dateKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const uid=()=>crypto.randomUUID();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10 12 3l9 7v11H3Z M9 21v-8h6v8',plan:'M5 5h14v16H5Z M8 3v4m8-4v4M5 10h14',notes:'M5 3h10l4 4v14H5Z M9 12h6m-6 4h6',goals:'M12 3a9 9 0 1 0 .01 0M12 7a5 5 0 1 0 .01 0M12 10v4m-2-2h4',me:'M16 7a4 4 0 1 0-8 0 4 4 0 0 0 8 0M4 21v-3a8 6 0 0 1 16 0v3',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',link:'m10 14 4-4M8 16l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m0 2 1-1a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.notes}"/></svg>`;
const fresh=()=>({version:1,profile:{name:'生活家',bio:'把时间留给重要的事，也留一点给自己。'},theme:'light',tasks:[],notes:[],goals:[]});
function valid(s){if(!s||s.version!==1||!s.profile||typeof s.profile.name!=='string'||!s.profile.name.trim()||s.profile.name.length>30||typeof s.profile.bio!=='string'||!['light','dark'].includes(s.theme))return false;const str=v=>typeof v==='string';const day=v=>str(v)&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!isNaN(new Date(v+'T12:00:00').getTime());return ['tasks','notes','goals'].every(k=>Array.isArray(s[k])&&s[k].length<=10000&&new Set(s[k].map(x=>x.id)).size===s[k].length&&s[k].every(x=>x&&str(x.id)&&/^[a-zA-Z0-9-]+$/.test(x.id)&&str(x.title)&&x.title.trim()&&x.title.length<=120))&&s.tasks.every(x=>day(x.date)&&str(x.time)&&(!x.time||/^([01]\d|2[0-3]):[0-5]\d$/.test(x.time))&&['task','event'].includes(x.kind)&&['normal','high'].includes(x.priority)&&typeof x.done==='boolean')&&s.notes.every(x=>['note','bookmark'].includes(x.kind)&&str(x.body)&&str(x.url)&&(!x.url||safeURL(x.url))&&day(x.date))&&s.goals.every(x=>Number.isFinite(x.current)&&Number.isFinite(x.target)&&x.target>0&&x.current>=0&&x.current<=x.target&&str(x.unit)&&str(x.next)&&day(x.date));}
function safeURL(v){try{return ['https:','http:'].includes(new URL(v).protocol)}catch{return false}}
let state=fresh(),loadError='';try{const raw=localStorage.getItem(KEY);if(raw){const s=JSON.parse(raw);if(!valid(s))throw Error();state=s}}catch{loadError='无法读取本地数据。原数据未被覆盖，请先导出原始备份后再重置。'}
let page='home',selectedDate=dateKey(),filter='all',noticeTimer;
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.style.display='block';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>el.style.display='none',3500)}
function commit(next){if(loadError){toast('请先导出原始备份并重置数据');return false}try{localStorage.setItem(KEY,JSON.stringify(next));state=next;render();return true}catch{toast('保存失败：浏览器存储不可用或空间不足，请导出备份。');return false}}
function change(fn){const next=structuredClone(state);fn(next);return commit(next)}
const empty=t=>`<div class="empty">${t}</div>`;
function taskList(items){return items.length?items.map(t=>`<div class="task ${t.done?'done':''}"><input type="checkbox" aria-label="完成 ${esc(t.title)}" data-toggle="${t.id}" ${t.done?'checked':''}><button class="task-body" data-edit="task" data-id="${t.id}"><span class="task-title">${esc(t.title)}</span><small>${esc(t.time||'全天')} · ${t.kind==='event'?'日程':'待办'}${t.date<dateKey()&&!t.done?' · 已逾期':''}</small></button><span class="tag ${t.priority==='high'?'urgent':''}">${t.priority==='high'?'优先处理':'按自己的节奏'}</span><button class="tiny" data-delete="tasks" data-id="${t.id}" aria-label="删除 ${esc(t.title)}">×</button></div>`).join(''):empty('这一天还没有安排<br>留一点空白，也可以添加一件小事。')}
function week(){const start=new Date(selectedDate+'T12:00:00');start.setDate(start.getDate()-(start.getDay()+6)%7);return `<div class="row"><button class="tiny" data-week="-7" aria-label="上一周">‹ 上周</button><span class="muted" style="font-size:14px">${esc(selectedDate.slice(0,7).replace('-',' 年 '))} 月</span><button class="tiny" data-week="7" aria-label="下一周">下周 ›</button></div><div class="week">${Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const key=dateKey(d);return `<button class="day ${key===selectedDate?'selected':''} ${key===dateKey()?'today':''}" data-date="${key}" aria-label="${key}" aria-pressed="${key===selectedDate}"><span>${['一','二','三','四','五','六','日'][i]}</span><b>${d.getDate()}</b></button>`}).join('')}</div>`}
const byDay=()=>state.tasks.filter(t=>t.date===selectedDate&&(filter==='all'||(filter==='done'?t.done:!t.done))).sort((a,b)=>a.time.localeCompare(b.time));
function goalList(items){return items.length?items.map(g=>`<div class="goal"><div class="row"><h3>${esc(g.title)}</h3><button class="tiny" data-edit="goal" data-id="${g.id}">更新</button></div><p>${g.next?'下一步：'+esc(g.next):'截止 '+esc(g.date)}</p><progress value="${g.current}" max="${g.target}" aria-label="${esc(g.title)}进度"></progress><div class="row"><span>${g.current} / ${g.target} ${esc(g.unit)}</span><b>${Math.round(g.current/g.target*100)}%</b><button class="tiny danger" data-delete="goals" data-id="${g.id}" aria-label="删除 ${esc(g.title)}">删除</button></div></div>`).join(''):empty('还没有设定目标<br>从一件真正想完成的事开始。')}
function noteList(items){return items.length?`<div class="note-grid">${items.map(n=>`<article class="note"><span class="eyebrow">${n.kind==='bookmark'?'BOOKMARK / 收藏':'NOTE / 笔记'}</span><h3>${esc(n.title)}</h3><p>${esc(n.body.slice(0,160))}${n.body.length>160?'…':''}</p>${n.kind==='bookmark'?`<a href="${esc(n.url)}" target="_blank" rel="noopener noreferrer" class="text-btn">打开收藏 ↗</a>`:''}<div class="note-footer"><span>${esc(n.date)}</span><span><button class="tiny" data-edit="note" data-id="${n.id}">编辑</button><button class="tiny" data-delete="notes" data-id="${n.id}">删除</button></span></div></article>`).join('')}</div>`:empty('灵感、心情、值得收藏的链接<br>把生活里的小发现留在这里。')}
function home(){const today=state.tasks.filter(t=>t.date===dateKey()),done=today.filter(t=>t.done).length;return `<section class="welcome row"><div><span class="eyebrow">MY PERSONAL SPACE</span><h1>你好，${esc(state.profile.name)}。</h1><p class="muted">新的一天，从照顾好自己的节奏开始。</p></div><button class="primary" data-add="task">${icon('plus')} 添加安排</button></section><div class="stats"><div class="stat"><span class="stat-icon">${icon('check')}</span><span class="stat-label">今日待完成</span><strong>${today.length-done}<small> 项</small></strong><small>已完成 ${done} 项安排</small></div><div class="stat"><span class="stat-icon">${icon('goals')}</span><span class="stat-label">进行中的目标</span><strong>${state.goals.filter(g=>g.current<g.target).length}<small> 个</small></strong><small>每一步，都算数</small></div><div class="stat"><span class="stat-icon">${icon('notes')}</span><span class="stat-label">收集的生活片段</span><strong>${state.notes.length}<small> 条</small></strong><small>记录让平凡闪光</small></div></div><div class="columns"><div class="stack"><section class="card"><div class="section-head"><h2>我的安排</h2><button class="text-btn" data-page="plan">全部安排 ↗</button></div>${week()}${taskList(byDay())}</section><section class="card"><div class="section-head"><h2>随手记一点</h2><span class="muted" style="font-size:13px">给生活一个落点</span></div><div class="quick">${[['note','notes','写笔记'],['bookmark','link','存链接'],['task','plan','加待办'],['goal','goals','定目标']].map(([a,i,l])=>`<button data-add="${a}">${icon(i)}${l}</button>`).join('')}</div></section><section class="card"><div class="section-head"><h2>最近记录</h2><button class="text-btn" data-page="notes">查看全部 ↗</button></div>${noteList(state.notes.slice(0,2))}</section></div><div class="stack"><section class="card"><div class="section-head"><h2>慢慢靠近目标</h2><button class="text-btn" data-add="goal">＋ 新目标</button></div>${goalList(state.goals.slice(0,3))}</section><section class="card"><div class="profile-cover"><span class="eyebrow" style="color:#a0dace">THIS IS ME</span><div class="avatar" style="margin-top:20px">${esc(state.profile.name.slice(0,1))}</div><h2>${esc(state.profile.name)}</h2><p>${esc(state.profile.bio)}</p><button class="text-btn" data-page="me">编辑我的名片 ↗</button></div><div class="quote">生活不用每一天都很满。<br>重要的是，有自己喜欢的方向。</div></section></div></div>`}
function other(){if(page==='plan')return `<div class="welcome row"><div><span class="eyebrow">ONE THING AT A TIME</span><h1>我的计划</h1><p class="muted">把想做的事，放进合适的时间里。</p></div><button class="primary" data-add="task">＋ 添加安排</button></div><div class="columns"><section class="card">${week()}<div class="filters">${[['all','全部'],['pending','待完成'],['done','已完成']].map(([v,l])=>`<button data-filter="${v}" class="${filter===v?'selected':''}">${l}</button>`).join('')}<button data-date="${dateKey()}">回到今天</button></div>${taskList(byDay())}</section><section class="card"><div class="section-head"><h2>接下来与待处理</h2></div>${taskList(state.tasks.filter(t=>!t.done&&t.date!==selectedDate).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,15).map(t=>({...t,title:t.date+' · '+t.title})))}</section></div>`;
if(page==='notes')return `<div class="welcome row"><div><span class="eyebrow">LITTLE THINGS, KEPT</span><h1>我的记录</h1><p class="muted">想法与发现，都值得被记住。</p></div><button class="primary" data-add="note">＋ 写记录</button></div><div class="filters">${[['all','全部记录'],['note','笔记'],['bookmark','收藏']].map(([v,l])=>`<button data-filter="${v}" class="${filter===v?'selected':''}">${l}</button>`).join('')}<button data-add="bookmark">＋ 收藏链接</button></div>${noteList(state.notes.filter(n=>filter==='all'||n.kind===filter))}`;
if(page==='goals')return `<div class="welcome row"><div><span class="eyebrow">SMALL STEPS, REAL PROGRESS</span><h1>我的目标</h1><p class="muted">不急着抵达，先向前一步。</p></div><button class="primary" data-add="goal">＋ 新目标</button></div><section class="card">${goalList(state.goals)}</section>`;
return `<div class="welcome"><span class="eyebrow">A SPACE OF YOUR OWN</span><h1>我的个人中心</h1></div><section class="card settings"><h2>个人名片</h2><form id="profile-form"><label class="field">昵称<input name="name" value="${esc(state.profile.name)}" required maxlength="30"></label><label class="field">个人签名<input name="bio" value="${esc(state.profile.bio)}" maxlength="160"></label><button class="primary">保存名片</button></form><div class="setting"><div><strong>深色模式</strong><p>选择更适合当前环境的外观</p></div><button class="secondary" id="theme" role="switch" aria-checked="${state.theme==='dark'}">${state.theme==='dark'?'已开启':'已关闭'}</button></div><div class="setting"><div><strong>备份与恢复</strong><p>数据只保存在此浏览器，不会随代码上传。清理浏览器前请备份。</p></div><div><button class="secondary" id="export">导出备份</button><button class="text-btn" id="import">导入备份</button><input id="import-file" type="file" accept="application/json,.json" hidden></div></div><div class="setting"><div><strong>体验示例</strong><p>仅在没有记录时加入几条示例，帮助你熟悉功能。</p></div><button class="secondary" id="demo" ${state.tasks.length+state.notes.length+state.goals.length?'disabled':''}>加载示例</button></div><div class="setting"><div><strong>清空本地数据</strong><p>删除此浏览器里的全部安排、记录和目标。</p></div><button class="secondary danger" id="reset">清空数据</button></div></section>`}
function render(){document.body.classList.toggle('dark',state.theme==='dark');document.getElementById('app').innerHTML=`<aside class="sidebar"><div class="brand"><span class="brand-mark">隅</span><div>一隅<small>MY LITTLE SPACE</small></div></div><nav class="nav" aria-label="主导航">${[['home','生活概览'],['plan','我的计划'],['notes','我的记录'],['goals','我的目标'],['me','个人中心']].map(([p,l])=>`<button data-page="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(p)}${l}</button>`).join('')}</nav><div class="side-bottom"><strong>属于自己的生活节奏</strong>一隅 · 本地个人空间<br>VERSION 1.0</div></aside><main><header class="topbar"><span>${new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'})}</span><div class="row"><span class="pill">本地保存 · 个人空间</span><button class="avatar" data-page="me" aria-label="编辑个人资料">${esc(state.profile.name.slice(0,1))}</button></div></header>${loadError?`<div class="error-banner">${loadError} <button data-page="me">前往设置</button></div>`:''}${page==='home'?home():other()}<footer class="footer">留一隅，给自己的生活。</footer></main>`;bind()}
const fields={task:[['title','安排名称','text'],['date','日期','date'],['time','时间（可留空）','time'],['kind','类型','select', [['task','待办'],['event','日程']]],['priority','优先级','select',[['normal','普通'],['high','优先']]]],note:[['title','标题','text'],['body','正文','textarea']],bookmark:[['title','标题','text'],['url','收藏链接','url'],['body','备注','textarea']],goal:[['title','目标名称','text'],['target','目标总量','number'],['current','当前完成','number'],['unit','单位（本 / 次 / 小时）','text'],['date','截止日期','date'],['next','下一步行动','text']]};
function openEditor(type,id){const key=type==='task'?'tasks':type==='goal'?'goals':'notes';const item=id?state[key].find(i=>i.id===id):null;if(item&&key==='notes')type=item.kind==='bookmark'?'bookmark':'note';const v=item||{date:selectedDate,time:'',kind:'task',priority:'normal',current:0,target:10};const dialog=document.getElementById('editor');dialog.innerHTML=`<form id="item-form"><h2 id="dialog-title">${id?'编辑':'添加'}${{task:'安排',note:'笔记',bookmark:'收藏',goal:'目标'}[type]}</h2>${fields[type].map(([n,l,t,opts])=>`<label class="field">${l}${t==='textarea'?`<textarea name="${n}" maxlength="20000">${esc(v[n]||'')}</textarea>`:t==='select'?`<select name="${n}">${opts.map(([val,label])=>`<option value="${val}" ${v[n]===val?'selected':''}>${label}</option>`).join('')}</select>`:`<input name="${n}" type="${t}" value="${esc(v[n]??'')}" ${['title','date','url','target','current'].includes(n)?'required':''} ${t==='number'?`min="${n==='target'?1:0}" max="1000000000" step="any"`:''} ${t==='text'?'maxlength="120"':''}>`}</label>`).join('')}<p id="form-error" class="danger" role="alert"></p><div class="actions"><button type="button" class="secondary" id="cancel">取消</button><button class="primary" type="submit">保存${type==='task'?'安排':''}</button></div></form>`;dialog.showModal();document.getElementById('cancel').onclick=()=>dialog.close();document.getElementById('item-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));Object.keys(data).forEach(k=>data[k]=data[k].trim());if(!data.title){document.getElementById('form-error').textContent='请填写名称';return}if(type==='bookmark'&&!safeURL(data.url)){document.getElementById('form-error').textContent='请输入以 https:// 或 http:// 开头的链接';return}if(type==='goal'){data.current=Number(data.current);data.target=Number(data.target);if(data.current>data.target){document.getElementById('form-error').textContent='当前完成量不能超过目标总量';return}}const result={...(item||{}),...data,id:item?.id||uid()};if(key==='notes')Object.assign(result,{kind:type==='bookmark'?'bookmark':'note',date:dateKey(),url:data.url||''});if(key==='tasks')result.done=item?.done||false;if(change(s=>{const i=s[key].findIndex(x=>x.id===result.id);if(i<0)s[key].unshift(result);else s[key][i]=result})){dialog.close();toast('已保存')}}}
function confirmAction(title,body,action){const d=document.getElementById('editor');d.innerHTML=`<h2 id="dialog-title">${title}</h2><p>${body}</p><div class="actions"><button class="secondary" id="cancel">取消</button><button class="primary" id="confirm">确认</button></div>`;d.showModal();document.getElementById('cancel').onclick=()=>d.close();document.getElementById('confirm').onclick=()=>{d.close();action()}}
function download(content,name){const url=URL.createObjectURL(new Blob([content],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;filter='all';render();window.scrollTo(0,0)});document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openEditor(b.dataset.add));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEditor(b.dataset.edit,b.dataset.id));document.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{selectedDate=b.dataset.date;render()});document.querySelectorAll('[data-week]').forEach(b=>b.onclick=()=>{const d=new Date(selectedDate+'T12:00:00');d.setDate(d.getDate()+Number(b.dataset.week));selectedDate=dateKey(d);render()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});document.querySelectorAll('[data-toggle]').forEach(b=>b.onchange=()=>{if(!change(s=>{const t=s.tasks.find(t=>t.id===b.dataset.toggle);t.done=!t.done}))render()});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>confirmAction('删除这条内容？','删除后无法撤销，你也可以先在个人中心导出备份。',()=>{if(change(s=>s[b.dataset.delete]=s[b.dataset.delete].filter(x=>x.id!==b.dataset.id)))toast('已删除')}));if(page!=='me')return;document.getElementById('profile-form').onsubmit=e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target));p.name=p.name.trim();if(!p.name){toast('昵称不能为空');return}if(change(s=>s.profile=p))toast('名片已更新')};document.getElementById('theme').onclick=()=>change(s=>s.theme=s.theme==='dark'?'light':'dark');document.getElementById('export').onclick=()=>{try{download(loadError?(localStorage.getItem(KEY)||''):JSON.stringify(state,null,2),`yiyu-backup-${dateKey()}.json`)}catch{toast('浏览器不允许读取存储，无法导出')}};document.getElementById('import').onclick=()=>document.getElementById('import-file').click();document.getElementById('import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5*1024*1024)throw Error();const next=JSON.parse(await f.text());if(!valid(next))throw Error();confirmAction('恢复这份备份？',`将替换当前数据：${next.tasks.length} 条安排、${next.notes.length} 条记录、${next.goals.length} 个目标。建议先导出当前备份。`,()=>{if(commit(next))toast('备份已恢复')})}catch{toast('备份格式无效或超过 5 MB，现有数据未修改。')}finally{e.target.value=''}};document.getElementById('reset').onclick=()=>confirmAction('清空全部本地数据？','包括个人名片、安排、记录和目标。此操作不可撤销，请先导出备份。',()=>{const old=loadError;loadError='';if(commit(fresh()))toast('已清空');else{loadError=old;render()}});document.getElementById('demo').onclick=()=>{change(s=>{s.tasks=[{id:uid(),title:'读书 20 分钟（示例）',date:dateKey(),time:'08:30',kind:'task',priority:'normal',done:true},{id:uid(),title:'梳理本周的重要事项（示例）',date:dateKey(),time:'10:00',kind:'task',priority:'high',done:false},{id:uid(),title:'留半小时散步（示例）',date:dateKey(),time:'18:30',kind:'event',priority:'normal',done:false}];s.goals=[{id:uid(),title:'读完 4 本好书（示例）',target:4,current:1,unit:'本',date:dateKey(),next:'今晚读完一个章节'},{id:uid(),title:'完成 12 次运动（示例）',target:12,current:5,unit:'次',date:dateKey(),next:'周末去户外走走'}];s.notes=[{id:uid(),title:'把生活调到喜欢的节奏（示例）',body:'不用一次改变所有事情。从早起后的一杯水，到睡前的几页书，小事也有自己的分量。',kind:'note',url:'',date:dateKey()},{id:uid(),title:'周末的小小计划（示例）',body:'去书店翻一本没读过的书，找一条安静的路散步。给自己一点没有安排的时间。',kind:'note',url:'',date:dateKey()}]});toast('已加入示例，可自由编辑或删除')}}
render();
// Feature-detected read-only WebMCP integration; ordinary browsers need no polyfill.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_life_overview',description:'读取当前浏览器中的安排、笔记和目标；只读，不上传或修改数据。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw Error('Expected an empty object');return structuredClone({tasks:state.tasks,notes:state.notes,goals:state.goals})}})).catch(()=>{})}catch{}}
